const isEven = (n) => n % 2 === 0;
const isOdd  = (n) => n % 2 !== 0; // not === 1: -3 % 2 is -1

isOdd(-3); // true

function grade(score) {
  if (typeof score !== 'number' || Number.isNaN(score)) return 'Invalid';
  if (score < 0 || score > 100) return 'Out of range';
  if (score >= 90) return 'A';
  if (score >= 80) return 'B';
  if (score >= 70) return 'C';
  return 'F';
}

console.log(grade(95), grade(72), grade(-5), grade('90'));

const toFahrenheit = (c) => c * 9 / 5 + 32;
const round = (x, digits = 1) => Math.round(x * 10 ** digits) / 10 ** digits;

console.log(toFahrenheit(37));          // 98.60000000000001
console.log(round(toFahrenheit(37)));   // 98.6

function max3(a, b, c) {
  let max = a;
  if (b > max) max = b;
  if (c > max) max = c;
  return max;
}

max3(4, 9, 2);      // 9
Math.max(4, 9, 2);  // 9 : the built-in version

function isPalindrome(text) {
  const clean = text.toLowerCase().replace(/[^a-z0-9]/g, '');
  let left = 0;
  let right = clean.length - 1;
  while (left < right) {
    if (clean[left] !== clean[right]) return false;
    left++;
    right--;
  }
  return true;
}

isPalindrome('Race car'); // true
isPalindrome('hello');    // false
